---
import "../styles/global.css";
---

<!doctype html>
<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Document</title>
    <link rel="preconnect" href="https://fonts.gstatic.com" />
    <link
      href="https://fonts.googleapis.com/css2?family=DM+Sans:ital,wght@0,400;0,500;1,700&family=Inter:wght@300;500&display=swap"
      rel="stylesheet"
    />
  </head>
  <body>
    <slot />
  </body>
</html>
---
import BaseLayout from "../layouts/BaseLayout.astro";
---

<BaseLayout>
    <header>
      <img src="/assets/img/logo.svg" alt="" />
      <div class="header--title-container">
        <h1>La próxima revolución en el intercambio de criptomonedas.</h1>
        <p>
          Batabit te ayuda a navegar entre los diferentes precios y tendencias.
        </p>
        <a class="header--button" href="#plans"
          >Conoce Nuestros Planes <span></span
        ></a>
      </div>
    </header>
    <main>
      <section class="main-exchange-container">
        <div class="backgroundImg"></div>
        <div class="main-exchange-container--title">
          <h2>Visibilizamos todas las tasas de cambio.</h2>
          <p>
            Traemos información en tiempo real de las casas de cambio y las
            monedas más importantes del mundo.
          </p>
        </div>
        <section class="main-tables-container">
          <div class="main-currency-table">
            <p class="currency-table--title __orange">Monedas</p>
            <div class="currency-table--container">
              <div class="currency-table--container--grid">
                <div class="grid__top-left">Bitcoin</div>
                <div class="grid__top-right">
                  $ 1.96 <span class="icon down"></span>
                </div>

                <div>Ethereum</div>
                <div>$ 0.07<span class="icon up"></span></div>

                <div>Ripple</div>
                <div>$ 2.15 <span class="icon down"></span></div>

                <div class="grid__bottom-left">Stellar</div>
                <div class="grid__bottom-right">
                  $ 4.96 <span class="icon down"></span>
                </div>
              </div>
            </div>
            <div class="currency-table--date __soft-orange">
              <p><b>Actualizado</b>: 19 Julio 23:45</p>
            </div>
          </div>
          <div class="main-currency-table">
            <p class="currency-table--title __blue">Comisiones</p>
            <div class="currency-table--container">
              <div class="currency-table--container--grid">
                <div class="grid__top-left">Bitrade</div>
                <div class="grid__top-right">$ 12.96</div>

                <div>Bitpreco</div>
                <div>$ 13.07</div>

                <div class="grid__bottom-left">Novadax</div>
                <div class="grid__bottom-right">$ 13.15</div>

                <div>Coinext</div>
                <div>$ 14.96</div>
              </div>
            </div>
            <div class="currency-table--date __soft-blue">
              <p><b>Actualizado</b>: 19 Julio 23:45</p>
            </div>
          </div>
        </section>
      </section>
      <section class="main-product-detail">
        <span class="product-detail--batata-log"></span>
        <div class="product-detail--title">
          <h2>Creamos un producto sin comparación.</h2>
          <p>Confiable y diseñado para su uso diario.</p>
        </div>
        <section class="product-cards--container">
          <article class="product-detail--card">
            <span class="icon-card clock"></span>
            <p class="product--card-title">Tiempo real</p>
            <p class="product--card-body">
              Nuestro API toma información minuto a minuto sobre las tasas que
              más determinan el comportamiento.
            </p>
          </article>
          <article class="product-detail--card">
            <span class="icon-card eye"></span>
            <p class="product--card-title">No hay tasas escondidas</p>
            <p class="product--card-body">
              Ni en la compra o al momento de exit, Batabit siempre te muestra
              el costo real de lo que estás adquiriendo.
            </p>
          </article>
          <article class="product-detail--card">
            <span class="icon-card dollar-sign"></span>
            <p class="product--card-title">Compara monedas</p>
            <p class="product--card-body">
              No más rumores, con Babtabit sabrás el valor real de cada moneda
              en el mercado actual.
            </p>
          </article>
          <article class="product-detail--card">
            <span class="icon-card check-circle"></span>
            <p class="product--card-title">Información confiable</p>
            <p class="product--card-body">
              Nuestras fuentes están 100% verificadas y continuamos auditando su
              contenido mientras se actualizan.
            </p>
          </article>
        </section>
      </section>
      <section class="bitcoin-img-container">
        <h2>Conócelo hoy.</h2>
      </section>
      <section id="plans" class="main-plans-container">
        <div class="plans--title">
          <h2>Escoge el plan que mejor se ajuste a ti.</h2>
          <p>Cualquier plan te da acceso completo a nuestra plataforma.</p>
        </div>
        <section class="plans-container--slider">
          <article class="plans-container--card">
            <div class="plan-info-container">
              <p class="recommended __bg-blue">Más vendido</p>
              <h3 class="plan-card--title">Pago Mensual</h3>
              <p class="plan-card--price"><span>$</span> 19</p>
              <p class="plan-card--saving">*Acceso a servicios Pro</p>
              <button class="plan-card--ca">Escoger este <span></span></button>
            </div>
          </article>
          <article class="plans-container--card">
            <p class="recommended">Recomendado</p>
            <div class="plan-info-container">
              <h3 class="plan-card--title">Pago Anual</h3>
              <p class="plan-card--price"><span>$</span> 99</p>
              <p class="plan-card--saving">
                *Ahorras $129 comparado al plan mensual.
              </p>
              <button class="plan-card--ca">Escoger este <span></span></button>
            </div>
          </article>
          <article class="plans-container--card">
            <div class="plan-info-container">
              <h3 class="plan-card--title">Pago Diario</h3>
              <p class="plan-card--price"><span>$</span> 17</p>
              <p class="plan-card--saving">
                *Acceso a servicios Pro durante un dia
              </p>
              <button class="plan-card--ca">Escoger este <span></span></button>
            </div>
          </article>
        </section>
      </section>
    </main>
    <footer>
      <section class="left">
        <ul>
          <li><a href="#">Linkedin</a></li>
          <li><a href="#">Crunchbase</a></li>
          <li><a href="#">Hackernews</a></li>
        </ul>
      </section>
      <section class="right">
        <img src="/assets/img/logo-footer.svg" alt="Logo de Batatabit 2020" />
      </section>
    </footer>
</BaseLayout>
/*
  1. Posicionamimento
  2. Modelo de caja (Box model) [margin, padding, tamaño]
  3. Tipografia
  4. Visuales [Shadow box, Border Radius]
  5. Otros
*/

:root {
  /* Colores */
  --bitcoin-orange: #f7931a;
  --soft-orange: #ffe9d5;
  --secondary-blue: #1a9af7;
  --soft-blue: #e7f5ff;
  --warm-black: #201e1c;
  --black: #282623;
  --grey: #bababa;
  --off-white: #faf8f7;
  --just-white: #fff;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  padding: 0;
}

html {
  font-size: 62.5%;
  font-family: "DM Sans", sans-serif;
}

header {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  width: 100%;
  min-width: 320px;
  height: 334px;
  text-align: center;
  background: linear-gradient(207.8deg, #201e1c 16.69%, #f7931a 100%);
}

header img {
  width: 150px;
  height: 24px;
  margin-top: 60px;
  align-self: center;
}

.header--title-container {
  width: 90%;
  min-width: 288px;
  max-width: 900px;
  height: 218px;
  margin-top: 40px;
  text-align: center;
  align-self: center;
}
.header--title-container h1 {
  font-size: 2.4rem;
  font-weight: bold;
  line-height: 2.6rem;
  color: var(--just-white);
}

.header--title-container p {
  margin-top: 25px;
  font-size: 1.4rem;
  font-weight: 500;
  line-height: 1.8rem;
  color: var(--soft-orange);
}

.header--title-container .header--button {
  position: absolute;
  left: calc(50% - 118px);
  top: 270px;
  display: block;
  margin-top: 35px;
  padding: 15px;
  width: 229px;
  height: 48px;
  background-color: var(--off-white);
  /* Sombra */
  box-shadow: 0px 4px 8px rgba(89, 73, 30, 0.16);
  border-radius: 5px;
  font-size: 1.4rem;
  font-weight: bold;
  text-decoration: none;
  color: var(--black);
}

.header--button span {
  display: inline-block;
  width: 13px;
  height: 8px;
  margin-left: 10px;
  background-image: url("/assets/icons/down-arrow.svg");
}

main {
  width: 100%;
  height: auto;
  background-color: var(--off-white);
}

.main-exchange-container {
  width: 100%;
  height: auto;
  padding-top: 80px;
  padding-bottom: 30px;
  text-align: center;
}

.main-exchange-container--title {
  width: 90%;
  min-width: 288px;
  max-width: 900px;
  margin: 0 auto;
}

.main-exchange-container .backgroundImg {
  width: 200px;
  height: 200px;
  margin: 0 auto;
  margin-bottom: 50px;
  background-image: url("/assets/img/Bitcoin.svg");
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.main-exchange-container h2 {
  margin-bottom: 30px;
  font-size: 2.4rem;
  font-weight: bold;
  line-height: 2.6rem;
  color: var(--black);
}

.main-exchange-container p {
  margin-bottom: 30px;
  font-size: 1.4rem;
  font-weight: 500;
  line-height: 1.6rem;
  color: #757575;
}

.main-currency-table {
  width: 70%;
  min-width: 235px;
  max-width: 500px;
  height: auto;
  margin: 0 auto;
  margin-bottom: 30px;
  font-family: "Inter", sans-serif;
}

.main-currency-table .currency-table--title {
  margin-bottom: 15px;
  font-size: 1.8rem;
  font-weight: bold;
  line-height: 2.3rem;
}

.__orange {
  color: var(--bitcoin-orange) !important;
}

.__blue {
  color: var(--secondary-blue) !important;
}

.currency-table--container--grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2px;
  width: 90%;
  min-width: 230px;
  max-width: 300px;
  height: 250px;
  margin: 0 auto;
  border-radius: 15px;
}

.currency-table--container--grid div {
  display: flex;
  align-items: center;
  width: auto;
  padding: 12px 10px;
  font-size: 1.6rem;
  font-weight: normal;
  line-height: 1.9rem;
  color: var(--grey);
  background-color: var(--just-white);
}

.currency-table--container--grid div:nth-child(even) {
  justify-content: center;
  color: #757575;
}

.currency-table--container--grid .grid__top-left {
  border-radius: 15px 0 0 0;
}

.currency-table--container--grid .grid__top-right {
  border-radius: 0 15px 0 0;
}

.currency-table--container--grid .grid__bottom-left {
  border-radius: 0 0 0 15px;
}

.currency-table--container
  .currency-table--container--grid
  .grid__bottom-right {
  border-radius: 0 0 15px 0;
}

.currency-table--container--grid .table__right {
  font-size: 1.4rem;
  font-weight: normal;
  line-height: 1.7rem;
  color: #757575;
}

.currency-table--container--grid .icon {
  display: inline-block;
  width: 15px;
  height: 15px;
  margin-left: 10px;
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

.currency-table--container--grid .icon.down {
  background-image: url("/assets/icons/trending-down.svg");
}

.currency-table--container--grid .icon.up {
  background-image: url("/assets/icons/trending-up.svg");
}

.currency-table--date {
  width: 190px;
  height: 30px;
  margin: 0 auto;
  margin-top: 16px;
  padding: 8px;
  background-color: var(--soft-orange);
  border-radius: 8px;
}

.__soft-blue {
  background-color: var(--soft-blue) !important;
}

.currency-table--date p {
  font-size: 1.2rem;
  font-weight: 300;
  line-height: 1.5rem;
  color: var(--warm-black);
}

.main-product-detail {
  position: relative;
  width: 100%;
  min-width: 320px;
  height: auto;
  padding: 20px 10px;
  background-color: var(--warm-black);
}

.product-detail--batata-log {
  position: absolute;
  width: 40px;
  height: 25px;
  top: -10px;
  left: calc(50% - 20px);
  background-image: url("/assets/icons/batata.svg");
}

.product-detail--title {
  width: 90%;
  min-width: 288px;
  height: auto;
  margin: 0 auto;
{}

