python3 - <<'EOF'
p='src/layouts/BaseLayout.astro'
s=open(p).read()
s=s.replace('import "../styles/global.css";\n','import "../styles/global.css";\n\nconst { title = "Document" } = Astro.props;\n')
s=s.replace('<title>Document</title>','<title>{title}</title>')
open(p,'w').write(s)
EOF
cat > src/pages/login.astro <<'EOF'
---
import BaseLayout from "../layouts/BaseLayout.astro";
---

<BaseLayout title="Ingresar | Batabit">
  <div class="login-page">
    <header class="login-header">
      <a href="/"><img src="/assets/img/logo.svg" alt="Batabit" /></a>
    </header>
    <main class="login-main">
      <section class="login-card">
        <h1>Ingresa a tu cuenta</h1>
        <p class="login-card--subtitle">
          Accede para ver las tasas de cambio en tiempo real.
        </p>
        <form class="login-form" action="#" method="post">
          <label for="email">Correo electrónico</label>
          <input
            id="email"
            name="email"
            type="email"
            autocomplete="email"
            placeholder="tu@correo.com"
            required
          />

          <label for="password">Contraseña</label>
          <input
            id="password"
            name="password"
            type="password"
            autocomplete="current-password"
            placeholder="••••••••"
            required
          />

          <a class="login-form--forgot" href="#">¿Olvidaste tu contraseña?</a>

          <button class="login-form--submit" type="submit">Ingresar</button>
        </form>
      </section>
    </main>
  </div>
</BaseLayout>
EOF
cat >> src/styles/global.css <<'EOF'

/* Login */
.login-page {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  min-width: 320px;
  background-color: var(--off-white);
}

.login-header {
  display: flex;
  justify-content: center;
  padding: 40px 0 90px;
  background: linear-gradient(207.8deg, #201e1c 16.69%, #f7931a 100%);
}

.login-header img {
  display: block;
  width: 150px;
  height: 24px;
}

.login-main {
  flex: 1;
  padding: 0 16px 60px;
}

.login-card {
  width: 100%;
  max-width: 440px;
  margin: -60px auto 0;
  padding: 30px 24px;
  background-color: var(--just-white);
  border-radius: 15px;
  box-shadow: 0 4px 8px rgba(89, 73, 30, 0.16);
}

.login-card h1 {
  font-size: 2.4rem;
  font-weight: bold;
  line-height: 2.6rem;
  text-align: center;
  color: var(--black);
}

.login-card--subtitle {
  margin: 15px 0 30px;
  font-size: 1.4rem;
  font-weight: 500;
  line-height: 1.8rem;
  text-align: center;
  color: #757575;
}

.login-form {
  display: flex;
  flex-direction: column;
}

.login-form label {
  margin-bottom: 8px;
  font-size: 1.4rem;
  font-weight: 500;
  line-height: 1.8rem;
  color: var(--black);
}

.login-form input {
  width: 100%;
  height: 48px;
  margin-bottom: 20px;
  padding: 0 14px;
  /* 16px evita el zoom automático en iOS */
  font-family: "DM Sans", sans-serif;
  font-size: 1.6rem;
  color: var(--black);
  background-color: var(--off-white);
  border: 2px solid transparent;
  border-radius: 5px;
  box-shadow: inset 0 0 0 1px var(--grey);
}

.login-form input::placeholder {
  color: #757575;
}

.login-form input:focus {
  outline: none;
  border-color: var(--bitcoin-orange);
  box-shadow: none;
}

.login-form--forgot {
  align-self: flex-end;
  margin-bottom: 25px;
  padding: 4px 0;
  font-size: 1.4rem;
  font-weight: 500;
  color: var(--black);
  text-decoration: underline;
  text-decoration-color: var(--bitcoin-orange);
  text-underline-offset: 3px;
}

.login-form--forgot:hover,
.login-form--forgot:focus-visible {
  color: var(--bitcoin-orange);
}

.login-form--submit {
  width: 100%;
  height: 48px;
  cursor: pointer;
  font-family: "DM Sans", sans-serif;
  font-size: 1.4rem;
  font-weight: bold;
  color: var(--just-white);
  background-color: var(--bitcoin-orange);
  border: 0;
  border-radius: 5px;
  box-shadow: 0 4px 8px rgba(89, 73, 30, 0.16);
}

.login-form--submit:hover {
  filter: brightness(0.95);
}

.login-form--submit:focus-visible {
  outline: 2px solid var(--black);
  outline-offset: 2px;
}

@media (min-width: 600px) {
  .login-header {
    padding-bottom: 110px;
  }
  .login-main {
    padding-top: 0;
  }
  .login-card {
    margin-top: -80px;
    padding: 40px 40px;
  }
}
EOF
